#[derive(Clone, Copy, Debug)]
enum BungeeJumpStep {
    Start,
    OnTouch,
}

fn bungee_jump_run(ctx: &Ctx, mut step: BungeeJumpStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            BungeeJumpStep::Start => {
                step = BungeeJumpStep::OnTouch;
                continue 'machine;
            }
            BungeeJumpStep::OnTouch => {
                'b1: {
                    let subject1 = ctx.call(Function::Rand, vec![Val::from(1), Val::from(3)])?;
                    let mut matched1 = false;
                    let no_case1 = !subject1.loosely_equals(&Val::from(1))
                        && !subject1.loosely_equals(&Val::from(2))
                        && !subject1.loosely_equals(&Val::from(3));
                    if !matched1 && subject1.loosely_equals(&Val::from(1)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::PercentHeal, vec![Val::from(-100), Val::from(0)])?;
                        ctx.call(
                            Function::MapAnnounce,
                            vec![
                                Val::from("umbala"),
                                ((Val::from("Bungee Jump: ") + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?)
                                    + Val::from(" : Kyaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa~~~~~~~")),
                                ctx.constant("BC_MAP")?,
                            ],
                        )?;
                        return Err(Stop::End);
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(2)) {
                        matched1 = true;
                    }
                    if matched1 {
                        ctx.call(Function::PercentHeal, vec![Val::from(-50), Val::from(0)])?;
                        ctx.call(
                            Function::MapAnnounce,
                            vec![
                                Val::from("umbala"),
                                ((Val::from("Bungee Jump: ") + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?)
                                    + Val::from(" : Wooooooaaaaaaaaaaaaaahhhhhhhhhhhh~~~~~~!")),
                                ctx.constant("BC_MAP")?,
                            ],
                        )?;
                        return Err(Stop::End);
                    }
                    if !matched1 && subject1.loosely_equals(&Val::from(3)) {
                        matched1 = true;
                    }
                    if matched1 {
                        if ctx.call(Function::Rand, vec![Val::from(1), Val::from(2)])? == 2 {
                            ctx.call(Function::PercentHeal, vec![Val::from(-99), Val::from(0)])?;
                            ctx.call(Function::Warp, vec![Val::from("nif_in"), Val::from(69), Val::from(15)])?;
                        }
                        return Err(Stop::End);
                    }
                }
                return Ok(Val::from(0));
            }
        }
    }
}

pub fn bungee_jump(ctx: &Ctx) -> Script {
    bungee_jump_run(ctx, BungeeJumpStep::Start, Vec::new()).map(|_| ())
}

pub fn bungee_jump_ontouch(ctx: &Ctx) -> Script {
    bungee_jump_run(ctx, BungeeJumpStep::OnTouch, Vec::new()).map(|_| ())
}

#[derive(Clone, Copy, Debug)]
enum JumpStep {
    Start,
    OnTouch,
}

fn jump_run(ctx: &Ctx, mut step: JumpStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            JumpStep::Start => {
                step = JumpStep::OnTouch;
                continue 'machine;
            }
            JumpStep::OnTouch => {
                ctx.call(Function::Warp, vec![Val::from("umbala"), Val::from(145), Val::from(166)])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn jump(ctx: &Ctx) -> Script {
    jump_run(ctx, JumpStep::Start, Vec::new()).map(|_| ())
}

pub fn jump_ontouch(ctx: &Ctx) -> Script {
    jump_run(ctx, JumpStep::OnTouch, Vec::new()).map(|_| ())
}
